CREATE TABLE `messages` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`member_id` text NOT NULL,
	`body` text NOT NULL,
	`created_at` text NOT NULL
);

CREATE TABLE `organiser_items` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`list` text NOT NULL,
	`label` text NOT NULL,
	`done` integer DEFAULT false NOT NULL
);
